<script setup lang="ts">
import { computed, ref, onMounted, onBeforeUnmount, watch, nextTick } from 'vue'
import { mountChartMotion, type ChartMotion } from './chart-motion'
const dataset=ref('A'),state=ref('ready'),selected=ref(0),root=ref<HTMLElement|null>(null)
let motion:ChartMotion|undefined
onMounted(()=>{if(root.value)motion=mountChartMotion(root.value,'.chusage-card')})
watch([dataset,state],async()=>{await nextTick();motion?.refresh()})
onBeforeUnmount(()=>motion?.destroy())
const cohorts=computed(()=>dataset.value==='A'?[{name:'Jan',n:100,counts:[100,60,null,30],age:3},{name:'Feb',n:50,counts:[50,0,10],age:2},{name:'Mar',n:0,counts:[0,0],age:1}]:[{name:'Jan',n:80,counts:[80,40,32,20],age:3},{name:'Feb',n:40,counts:[40,null,8],age:2},{name:'Mar',n:20,counts:[20,10],age:1}])
const cells=computed(()=>cohorts.value.flatMap(c=>Array.from({length:4},(_,m)=>{const future=m>c.age,count=future?null:c.counts[m],pct=future||count===null||c.n===0?null:100*count/c.n;return{name:c.name,n:c.n,m,count,pct,kind:future?'future':count===null?'missing':c.n===0?'undefined':'observed'}})))
const label=(c:typeof cells.value[number])=>c.kind==='future'?'Future':c.kind==='missing'?'Missing':c.kind==='undefined'?'N/A':c.pct+'%'
const band=(c:typeof cells.value[number])=>c.pct===null?c.kind:Math.min(3,Math.floor(c.pct/25))
function reset(){dataset.value='A';state.value='ready';selected.value=0}
</script>
<template>
<section ref="root" class="chusage-demo" aria-label="Local cohort retention example"><p>Synthetic signup cohorts, fixed denominator per row. M0 is signup; M1–M3 are elapsed monthly periods, not calendar month columns. Retained means active in that period among the original cohort.</p><div class="chusage-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><button type="button" @click="reset">Reset example</button></div><div class="chusage-card"><template v-if="state==='ready'"><div class="chusage-grid" role="group" aria-label="Select cohort and elapsed period"><span aria-hidden="true"></span><span v-for="m in 4" :key="m" class="chusage-axis">M{{ m-1 }}</span><template v-for="(c,r) in cohorts" :key="c.name"><span class="chusage-axis">{{ c.name }}<small>N={{ c.n }}</small></span><button v-for="(cell,m) in cells.slice(r*4,r*4+4)" :key="m" type="button" class="chusage-cell" :class="['chusage-band-'+band(cell),{selected:selected===r*4+m}]" :data-index="r*4+m" :data-kind="cell.kind" :data-band="band(cell)" :aria-label="cell.name+' M'+cell.m+': '+label(cell)" :aria-pressed="selected===r*4+m" data-cm="fade" @focus="selected=r*4+m" @click="selected=r*4+m">{{ label(cell) }}</button></template></div><ul class="chusage-legend" aria-label="Fixed retention thresholds"><li v-for="(b,i) in ['0–24%','25–49%','50–74%','75–100%']" :key="b"><i :class="'chusage-band-'+i" aria-hidden="true"></i>{{ b }}</li></ul><p class="chusage-key">Future = not elapsed (dashed). Missing = elapsed, count unknown (hatched). N/A = known zero-size cohort, percentage undefined (gray). Measured 0% is not any of those.</p><p role="status">{{ cells[selected].name }} M{{ cells[selected].m }}: {{ label(cells[selected]) }}. {{ cells[selected].kind==='future'?'Period has not elapsed; no count.':cells[selected].kind==='missing'?'Count unavailable; denominator '+cells[selected].n+'.':'Active '+cells[selected].count+' / original '+cells[selected].n+(cells[selected].kind==='undefined'?'; division by zero is undefined.':'.') }}</p><table class="chusage-data"><caption>Exact retained counts and percentages, dataset {{ dataset }}</caption><thead><tr><th scope="col">Cohort/age</th><th scope="col">Active / N</th><th scope="col">Retained</th></tr></thead><tbody><tr v-for="cell in cells" :key="cell.name+cell.m"><th scope="row">{{ cell.name }} M{{ cell.m }}</th><td>{{ cell.kind==='future'?'Not elapsed':cell.kind==='missing'?'Unknown / '+cell.n:cell.count+' / '+cell.n }}</td><td>{{ label(cell) }}</td></tr></tbody></table></template><p v-else role="status" class="chusage-state">{{ state==='loading'?'Loading demonstration only; no request is running. Cohorts are withheld.':'No cohort records in this demonstration state. Choose Ready to recover.' }}</p></div></section>
</template>
<style scoped>
.chusage-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.chusage-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.chusage-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.chusage-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.chusage-demo button{padding:4px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.chusage-demo :is(button,select):focus-visible{outline:3px solid var(--vp-c-text-1);outline-offset:3px}.chusage-grid{display:grid;grid-template-columns:44px repeat(4,minmax(0,1fr));gap:6px;margin:20px 0;align-items:center}.chusage-axis{font-size:12px;text-align:center}.chusage-axis small{display:block;font-size:10px}.chusage-demo .chusage-cell{min-height:44px;font-size:11px;color:#09252e;border:2px solid transparent;border-radius:6px;cursor:pointer}.chusage-demo .chusage-cell.selected{border-color:var(--vp-c-text-1);outline:1px solid var(--vp-c-bg);outline-offset:-4px}.chusage-demo .chusage-band-0{background:#e0f2fe}.chusage-demo .chusage-band-1{background:#7dd3fc}.chusage-demo .chusage-band-2{background:#0369a1;color:white}.chusage-demo .chusage-band-3{background:#082f49;color:white}.chusage-demo .chusage-band-missing{background:repeating-linear-gradient(135deg,#f1f5f9 0 4px,#cbd5e1 4px 6px);color:#09252e}.chusage-demo .chusage-band-future{background:transparent;color:var(--vp-c-text-2);border:1px dashed var(--vp-c-text-2)}.chusage-demo .chusage-band-undefined{background:#d1d5db;color:#09252e}.chusage-legend{display:flex;gap:8px 14px;flex-wrap:wrap;list-style:none!important;padding:0!important;font-size:12px}.chusage-legend li{display:flex;gap:6px;align-items:center;margin:0!important}.chusage-legend i{width:16px;height:16px;border:1px solid #64748b;display:inline-block}.chusage-data{display:table!important;width:100%;font-size:12px}.chusage-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.chusage-data :is(td,th){padding:6px!important}.chusage-key{font-size:12px;color:var(--vp-c-text-2)}.chusage-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}
</style>
